#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n, t;
    cin >> n >> t;

    vector<int> arr(t);
    for (int i = 0; i < t; ++i) {
        cin >> arr[i];
    }

    sort(arr.begin(), arr.end());

    int result = arr[n - 1] - arr[0];
    for (int i = 1; i <= t - n; ++i) {
        result = min(result, arr[i + n - 1] - arr[i]);
    }

    cout << result;
    return 0;
}

